class Solution {
    public List<Integer> targetIndices(int[] nums,int target){
        Arrays.sort(nums);
        List<Integer> answer=new ArrayList<>();
        for(int i=0;i<nums.length;i++)if(nums[i]==target)answer.add(i);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun targetIndices(nums:IntArray,target:Int):List<Int>{
        nums.sort();
        return nums.indices.filter{
            nums[it]==target
        }
    }
}

code.cpp:
class Solution {
    public: vector<int> targetIndices(vector<int>& nums,int target){
        sort(nums.begin(),nums.end());
        vector<int> answer;
        for(int i=0;i<(int)nums.size();++i)if(nums[i]==target)answer.push_back(i);
        return answer;
    }
};
